<?php
declare(strict_types=1);
const STATUSES=['new','analyzing','resolved','ignored'];
$root=dirname(__DIR__);$cfgFile="$root/admin-config.php";$store="$root/feedback-data";$stateFile="$store/.admin-state.json";
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function stop(string $m,int $c=500):never{http_response_code($c);header('Cache-Control: no-store');echo '<body style="font:15px Segoe UI;background:#100d17;color:#eee;padding:40px"><h2>Feedback Control Panel</h2><p>'.h($m).'</p>';exit;}
function rid(string $v):bool{return preg_match('/^[A-Za-z0-9._-]{8,100}$/',$v)===1;}
function rpath(string $s,string $id):?string{return rid($id)?"$s/$id.json":null;}
function jsonfile(string $p):?array{$r=@file_get_contents($p);if($r===false)return null;$d=json_decode($r,true);return is_array($d)?$d:null;}
function loadstates(string $p):array{return is_file($p)?(jsonfile($p)??[]):[];}
function savestates(string $p,array $d):bool{$j=json_encode($d,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);if($j===false)return false;$t=$p.'.tmp-'.bin2hex(random_bytes(4));if(@file_put_contents($t,$j."\n",LOCK_EX)===false)return false;return @rename($t,$p);}
function status(mixed $v):string{$v=strtolower((string)$v);return in_array($v,STATUSES,true)?$v:'new';}
function label(string $s):string{return ['new'=>'New','analyzing'=>'In analysis','resolved'=>'Resolved','ignored'=>'Ignored'][$s]??'New';}
function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return (string)$_SESSION['csrf'];}
function checkcsrf():void{if(empty($_POST['csrf'])||empty($_SESSION['csrf'])||!hash_equals((string)$_SESSION['csrf'],(string)$_POST['csrf']))stop('Invalid or expired request.',403);}
function issue(array $r):string{$t='[Feedback] '.($r['summary']??'Untitled');$b="Report: `".($r['report_id']??'')."`\nVersion: `".($r['app_version']??'?')."`\nCategory: ".($r['category']??'Unknown')."\n\n## Description\n".($r['description']??'');if(is_array($r['exception']??null))$b.="\n\n## Exception\n`".($r['exception']['type']??'')."`\n".($r['exception']['message']??'');return 'https://github.com/XaRaBaS7/PS5-FFPFSC-Renamer/issues/new?title='.rawurlencode($t).'&body='.rawurlencode($b);}
header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: no-referrer');header("Content-Security-Policy: default-src 'self'; style-src 'self' 'unsafe-inline'; form-action 'self'; frame-ancestors 'none'");header('Cache-Control: no-store');
if(!is_file($cfgFile))stop('Create ffpfsc/admin-config.php from admin-config.example.php.',503);$cfg=require $cfgFile;if(!is_array($cfg))stop('Invalid admin-config.php.',503);$user=trim((string)($cfg['username']??''));$hash=trim((string)($cfg['password_hash']??''));if($user===''||$hash===''||str_contains($hash,'REPLACE_WITH_PASSWORD_HASH'))stop('Configure a real username and password hash.',503);
session_name(preg_replace('/[^A-Za-z0-9_-]/','',(string)($cfg['session_name']??'ffpfsc_feedback_admin'))?:'ffpfsc_feedback_admin');session_set_cookie_params(['path'=>'/ffpfsc/admin/','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);session_start();
$auth=($_SESSION['auth']??false)===true;$err='';if(!$auth&&($_SERVER['REQUEST_METHOD']??'')==='POST'&&isset($_POST['login'])){if(hash_equals($user,trim((string)($_POST['username']??'')))&&password_verify((string)($_POST['password']??''),$hash)){session_regenerate_id(true);$_SESSION['auth']=true;$_SESSION['csrf']=bin2hex(random_bytes(24));header('Location: ./',true,303);exit;}usleep(350000);$err='Invalid username or password.';}
if(!$auth){?><!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Feedback Admin</title><style>body{margin:0;min-height:100vh;display:grid;place-items:center;background:#0d0b12;color:#eee;font:14px Segoe UI}.card{width:min(420px,90vw);padding:28px;background:#17131f;border:1px solid #342946;border-radius:14px}small{color:#65d4e6}input,button{width:100%;box-sizing:border-box;padding:11px;margin-top:10px;border-radius:8px;border:1px solid #40354f;background:#100d17;color:#fff}button{background:#543776;border:0;font-weight:700}.e{color:#ff9eb0}</style><form class="card" method="post"><small>PS5 FFPFSC Renamer</small><h2>Feedback Control Panel</h2><?php if($err):?><p class="e"><?=h($err)?></p><?php endif;?><input type="hidden" name="login" value="1"><input name="username" placeholder="Username" required autofocus><input type="password" name="password" placeholder="Password" required><button>Sign in</button></form><?php exit;}
if(!is_dir($store)&&!@mkdir($store,0700,true)&&!is_dir($store))stop('feedback-data is not writable.');$states=loadstates($stateFile);$flash='';
if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&!isset($_POST['login'])){checkcsrf();$a=(string)($_POST['action']??'');if($a==='logout'){$_SESSION=[];session_destroy();header('Location: ./',true,303);exit;}$id=trim((string)($_POST['report_id']??''));$p=rpath($store,$id);if(!$p||!is_file($p))$flash='Report not found.';elseif($a==='status'){$states[$id]=['status'=>status($_POST['status']??'new'),'updated_at'=>gmdate('c')];$flash=savestates($stateFile,$states)?'Status updated.':'Could not save status.';}elseif($a==='delete'){$flash=@unlink($p)?'Report deleted.':'Could not delete report.';unset($states[$id]);savestates($stateFile,$states);}}
if(isset($_GET['download'])){$id=(string)$_GET['download'];$p=rpath($store,$id);if(!$p||!is_file($p))stop('Report not found.',404);header('Content-Type: application/json');header('Content-Disposition: attachment; filename="'.$id.'.json"');readfile($p);exit;}
$reports=[];foreach(glob("$store/*.json")?:[] as $p){$r=jsonfile($p);if(!$r)continue;$id=(string)($r['report_id']??pathinfo($p,PATHINFO_FILENAME));if(!rid($id))continue;$st=status($states[$id]['status']??'new');$reports[]=['id'=>$id,'created'=>(string)($r['created_at']??''),'category'=>(string)($r['category']??'Unknown'),'summary'=>(string)($r['summary']??'(no summary)'),'version'=>(string)($r['app_version']??'?'),'status'=>$st,'mtime'=>@filemtime($p)?:0];}usort($reports,fn($a,$b)=>(strtotime($b['created'])?:$b['mtime'])<=>(strtotime($a['created'])?:$a['mtime']));$f=(string)($_GET['status']??'new');$all=$f==='all';if(!$all)$f=status($f);$visible=$all?$reports:array_values(array_filter($reports,fn($r)=>$r['status']===$f));$counts=array_fill_keys(STATUSES,0);foreach($reports as $r)$counts[$r['status']]++;
$sel=null;if(isset($_GET['report'])){$p=rpath($store,(string)$_GET['report']);if($p&&is_file($p))$sel=jsonfile($p);}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Feedback Control Panel</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#0d0b12;color:#eee;font:13px Segoe UI,Arial}a{color:#82d9ea;text-decoration:none}.top{height:62px;padding:0 20px;display:flex;align-items:center;justify-content:space-between;background:#121019;border-bottom:1px solid #2b2334}.top small{display:block;color:#65d4e6}.wrap{max-width:1450px;margin:auto;padding:20px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.stat,.panel{background:#17131f;border:1px solid #30273a;border-radius:10px}.stat{padding:12px}.stat span{color:#9f97ad;font-size:10px}.stat b{display:block;font-size:22px}.filters{display:flex;gap:7px;margin:14px 0;flex-wrap:wrap}.pill,.btn{padding:7px 10px;border:1px solid #40334d;border-radius:7px;background:#211a2a;color:#ddd;display:inline-block}.pill.on{background:#482f60;color:white}.layout{display:grid;grid-template-columns:1.2fr .8fr;gap:14px}.panel{overflow:hidden}.panel h3{margin:0;padding:13px;border-bottom:1px solid #30273a}table{width:100%;border-collapse:collapse}th,td{padding:10px;border-bottom:1px solid #282031;text-align:left;vertical-align:top}th{font-size:10px;color:#948a9f}.muted{color:#9f97ad}.badge{font-size:10px;padding:3px 7px;border-radius:999px;background:#39264e}.badge.analyzing{background:#123542}.badge.resolved{background:#173528}.badge.ignored{background:#302d34}.detail{padding:14px}.box{white-space:pre-wrap;overflow:auto;max-height:260px;background:#100d17;border:1px solid #2d2437;border-radius:7px;padding:10px;font:11px Consolas}.row{display:flex;gap:7px;flex-wrap:wrap;align-items:center}.btn{cursor:pointer}select{padding:7px;background:#100d17;color:#eee;border:1px solid #40334d;border-radius:7px}.danger{border-color:#71394a;color:#ffbecb}.flash{padding:9px 11px;margin-bottom:12px;background:#173528;border-radius:7px}@media(max-width:950px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}</style></head><body><header class="top"><div><small>PS5 FFPFSC Renamer</small><b>Feedback Control Panel</b></div><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="logout"><button class="btn">Sign out</button></form></header><main class="wrap"><?php if($flash):?><div class="flash"><?=h($flash)?></div><?php endif;?><section class="stats"><div class="stat"><span>Total</span><b><?=count($reports)?></b></div><?php foreach(STATUSES as $s):?><div class="stat"><span><?=h(label($s))?></span><b><?=$counts[$s]?></b></div><?php endforeach;?></section><nav class="filters"><a class="pill <?=$all?'on':''?>" href="?status=all">All</a><?php foreach(STATUSES as $s):?><a class="pill <?=(!$all&&$f===$s)?'on':''?>" href="?status=<?=h($s)?>"><?=h(label($s))?> (<?=$counts[$s]?>)</a><?php endforeach;?></nav><section class="layout"><div class="panel"><h3>Reports</h3><?php if(!$visible):?><p class="detail muted">No reports in this view.</p><?php else:?><table><thead><tr><th>Date</th><th>Type</th><th>Summary</th><th>Status</th></tr></thead><tbody><?php foreach($visible as $r):?><tr><td class="muted"><?=h($r['created'])?></td><td><?=h($r['category'])?><br><span class="muted">v<?=h($r['version'])?></span></td><td><a href="?status=<?=h($all?'all':$f)?>&report=<?=h($r['id'])?>"><b><?=h($r['summary'])?></b></a><br><span class="muted"><?=h($r['id'])?></span></td><td><span class="badge <?=h($r['status'])?>"><?=h(label($r['status']))?></span></td></tr><?php endforeach;?></tbody></table><?php endif;?></div><div class="panel"><h3>Report details</h3><?php if(!$sel):?><p class="detail muted">Select a report.</p><?php else:$id=(string)($sel['report_id']??'');$st=status($states[$id]['status']??'new');?><div class="detail"><div class="row"><span class="badge <?=h($st)?>"><?=h(label($st))?></span><span class="muted">v<?=h($sel['app_version']??'?')?></span></div><h3><?=h($sel['summary']??'')?></h3><p style="white-space:pre-wrap"><?=h($sel['description']??'')?></p><div class="row"><form method="post" class="row"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="report_id" value="<?=h($id)?>"><select name="status"><?php foreach(STATUSES as $s):?><option value="<?=h($s)?>" <?=$s===$st?'selected':''?>><?=h(label($s))?></option><?php endforeach;?></select><button class="btn">Update</button></form><a class="btn" href="?download=<?=h($id)?>">Download JSON</a><a class="btn" target="_blank" rel="noopener" href="<?=h(issue($sel))?>">Prepare GitHub issue</a><form method="post" onsubmit="return confirm('Delete this report permanently?')"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="report_id" value="<?=h($id)?>"><button class="btn danger">Delete</button></form></div><h4>Diagnostics</h4><div class="box"><?=h(json_encode($sel['diagnostics']??[],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE))?></div><?php if(is_array($sel['exception']??null)):?><h4>Exception</h4><div class="box"><?=h(($sel['exception']['type']??'').': '.($sel['exception']['message']??'')."\n\n".($sel['exception']['traceback']??''))?></div><?php endif;?><?php if(!empty($sel['activity'])&&is_array($sel['activity'])):?><h4>Recent activity</h4><div class="box"><?=h(implode("\n",array_map('strval',$sel['activity'])))?></div><?php endif;?></div><?php endif;?></div></section></main></body></html>
